:root {
  --bg: #0f1115;
  --card: #1a1d24;
  --card-hover: #21252e;
  --border: #2a2f3a;
  --text: #e6e8ec;
  --muted: #8a91a0;
  --accent: #5b9dff;
  --danger: #ff6b6b;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
}

h1 { font-size: 1.4rem; margin: 0; }

.header-actions { display: flex; gap: .5rem; }

main {
  max-width: 760px;
  margin: 0 auto;
  padding: 1.5rem;
}

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1rem;
  margin-bottom: 1.25rem;
}

.row { display: flex; gap: .5rem; margin-bottom: .5rem; }
.row input { flex: 1; }

input, textarea, button, label.ghost {
  font: inherit;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: #12151b;
  color: var(--text);
  padding: .55rem .7rem;
}

textarea { width: 100%; resize: vertical; }

input:focus, textarea:focus { outline: none; border-color: var(--accent); }

button {
  cursor: pointer;
  background: var(--accent);
  border: none;
  color: #0b1220;
  font-weight: 600;
  padding: .55rem 1.1rem;
}
button:hover { filter: brightness(1.1); }

.ghost {
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}
.ghost:hover { color: var(--text); border-color: var(--accent); }

.toolbar { margin-bottom: 1rem; }
#search { width: 100%; }

.tag-cloud { display: flex; flex-wrap: wrap; gap: .4rem; margin-bottom: 1rem; }
.tag-pill {
  font-size: .8rem;
  padding: .2rem .6rem;
  border-radius: 999px;
  background: var(--card);
  border: 1px solid var(--border);
  color: var(--muted);
  cursor: pointer;
}
.tag-pill:hover { color: var(--text); }
.tag-pill.active { background: var(--accent); color: #0b1220; border-color: var(--accent); }

.list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: .6rem; }

.item {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: .8rem 1rem;
  display: flex;
  gap: .75rem;
  align-items: flex-start;
}
.item:hover { background: var(--card-hover); }

.favicon { width: 20px; height: 20px; margin-top: 3px; flex-shrink: 0; border-radius: 4px; }

.item-body { flex: 1; min-width: 0; }
.item-title { font-weight: 600; color: var(--text); text-decoration: none; word-break: break-word; }
.item-title:hover { color: var(--accent); }
.item-url { font-size: .8rem; color: var(--muted); word-break: break-all; }
.item-desc { font-size: .9rem; color: var(--text); margin: .35rem 0 0; }
.item-tags { display: flex; flex-wrap: wrap; gap: .3rem; margin-top: .4rem; }
.item-tags .tag-pill { cursor: pointer; }

.item-actions { display: flex; gap: .35rem; flex-shrink: 0; }
.icon-btn {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--border);
  padding: .3rem .5rem;
  font-size: .8rem;
}
.icon-btn:hover { color: var(--text); }
.icon-btn.danger:hover { color: var(--danger); border-color: var(--danger); }

.empty { text-align: center; color: var(--muted); padding: 2rem; }

